// CSD_RATIONALE_BEGIN
// Root cause analysis of the 52%-ceiling: attempt 43 (best at 52%) uses hard
// parser-constrained generation with schema-token group boosting, but 134/300
// answers are semantically wrong despite valid syntax. The dominant failure
// pattern is identifier hallucination — the model generates plausible-looking
// but wrong table/column names that the SQL grammar accepts because it has no
// schema awareness.
//
// Key change vs attempt 43: Replace Phase 3's step-by-step
// GroupBoostedConstrainedStep loop with a single call to
// RegenerateUnitOnGroundingFailure. This helper generates SQL unit by unit,
// detecting each completed schema symbol (table or column name) and checking
// whether it is grounded in the prompt context. When an ungrounded identifier
// is found it rolls back to the last accepted checkpoint, penalizes that
// identifier, and regenerates — up to maxRetries=3 times per unit before
// accepting to preserve termination. This directly attacks the identifier-
// hallucination failure mode.
//
// All other phases are kept identical to attempt 43 (best verified):
// Phase 1: 5-step unconstrained preamble; detect "<<" with RenderedEndsWith.
// Phase 2: Force OpenConstrainedSpan if "<<" not naturally emitted.
// Phase 3: RegenerateUnitOnGroundingFailure with budget = maxSteps-steps-20,
//          maxRetries=3, maxRollbackBudget=20.
// Phase 4: CloseConstrainedSpan (if complete) or CloseSpanWithinBudget (up to
//          20 steps) as final fallback.
//
// Guidance is kept close to attempt 43 (the best) with an added JOIN note.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble (loop, guard includes !insideConstrainedOut):
//   insideConstrainedOut can only flip true when RenderedEndsWith fires, at
//   which point we set currentConstrainedOut := []. IsValidPrefix([]) holds
//   by the method precondition. On EOS break, insideConstrainedOut stays
//   false, making the implication vacuously true.
//
// Phase 2 OpenConstrainedSpan (only when !insideConstrainedOut):
//   Helper postcondition sets currentConstrainedOut := []; IsValidPrefix([])
//   holds by precondition.
//
// Phase 3 RegenerateUnitOnGroundingFailure:
//   Helper postcondition guarantees parser.IsValidPrefix(resultConstrained).
//   We set currentConstrainedOut := resultConstrained, preserving the
//   invariant. insideConstrainedOut stays true (no span close inside this
//   helper).
//
// Phase 4a CloseConstrainedSpan: requires parser.IsCompletePrefix which we
//   check first; helper sets insideConstrainedOut := false (implication
//   vacuously true) and clears currentConstrainedOut.
// Phase 4b CloseSpanWithinBudget: postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2: progress |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most
//   1 token (0 on EOS, 1 otherwise). Invariant preserved per iteration.
// Phase 2: OpenConstrainedSpan appends exactly 1 token and steps += 1.
//   Net 1:1, invariant preserved.
// Phase 3: RegenerateUnitOnGroundingFailure postcondition (cost <= budget)
//   implies |resultConstrained| - |currentConstrainedOut| <= genBudget.
//   With currentConstrainedOut = [] and stablePrefix = generated (since
//   |currentConstrainedOut|=0), |generated_new| = |generated_old| +
//   |resultConstrained| <= |generatedPrefix| + steps_old + genBudget =
//   |generatedPrefix| + steps_new. Invariant preserved.
// Phase 4a: CloseConstrainedSpan appends at most 1 token, steps += 1.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <=
//   |generated| + closeBudget; we set steps += closeBudget. Both preserve
//   |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. Use JOINs to combine information from multiple tables. For counting with group conditions use GROUP BY with HAVING COUNT(*). No explanation, no markdown, no column aliases, no table aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let the model emit "SQL: <<" prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Grounding-checked SQL generation.
// RegenerateUnitOnGroundingFailure generates SQL unit by unit, rolling back
// and resampling any completed schema symbol (table/column name) that is not
// grounded in the prompt context. maxRetries=3 per unit, maxRollbackBudget=20.
if insideConstrainedOut && steps < maxSteps {
  var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
  var constrainedPrompt := prompt + stablePrefix;
  var reserveSteps: nat := 20;
  var available := maxSteps - steps;
  var genBudget: nat;
  if available > reserveSteps {
    genBudget := available - reserveSteps;
  } else {
    genBudget := 0;
  }
  if genBudget > 0 {
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, genBudget, 3, 20
    );
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + genBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 20 { closeBudget := remaining; } else { closeBudget := 20; }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

